@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&display=swap');

:root {
  --bg-color: #F5F2ED;
  --text-color: #1A1A1A;
  --color-terracotta: #D36C50;
  --color-sage: #92ACA1;
  --color-sand: #E3B48F;
  --font-serif: 'Playfair Display', serif;
  --font-sans: 'Inter', sans-serif;
  --nav-height: 80px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  font-family: var(--font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 500;
  line-height: 1.2;
  margin-bottom: 1rem;
}

a {
  color: inherit;
  text-decoration: none;
}

p {
  margin-bottom: 1.5rem;
  font-size: 1.125rem;
  font-weight: 300;
}

/* Layout */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 5vw;
}

.section {
  padding: 8vw 0;
}

/* Header & Nav */
.header {
  height: var(--nav-height);
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
  z-index: 100;
  padding: 0 5vw;
}

.logo {
  font-family: var(--font-serif);
  font-size: 2rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.desktop-nav {
  display: none;
}

@media (min-width: 768px) {
  .desktop-nav {
    display: flex;
    gap: 2.5rem;
  }
  .desktop-nav a {
    font-size: 1rem;
    font-weight: 400;
    transition: opacity 0.3s ease;
  }
  .desktop-nav a:hover {
    opacity: 0.6;
  }
  .hamburger {
    display: none;
  }
}

.hamburger {
  background: none;
  border: none;
  cursor: pointer;
  width: 40px;
  height: 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-end;
  gap: 6px;
  z-index: 101;
  position: relative;
}

.hamburger span {
  display: block;
  width: 30px;
  height: 2px;
  background-color: var(--text-color);
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.hamburger.is-active span:nth-child(1) {
  transform: translateY(8px) rotate(45deg);
}
.hamburger.is-active span:nth-child(2) {
  opacity: 0;
}
.hamburger.is-active span:nth-child(3) {
  transform: translateY(-8px) rotate(-45deg);
}

.mobile-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: var(--bg-color);
  z-index: 90;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-overlay.is-active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-nav {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  text-align: center;
}

.mobile-nav a {
  font-family: var(--font-serif);
  font-size: 3rem;
  font-style: italic;
  font-weight: 400;
}

/* Home Hero */
.hero-section {
  min-height: 70vh;
  display: flex;
  align-items: center;
}

.hero-title {
  font-size: clamp(3rem, 8vw, 7rem);
  max-width: 1200px;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

/* Media Showcase */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2vw;
  margin-bottom: 8vw;
}

@media (min-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr 1fr 1fr;
  }
}

.media-block {
  aspect-ratio: 4/5;
  width: 100%;
}

.media-block.terracotta { background-color: var(--color-terracotta); }
.media-block.sage { background-color: var(--color-sage); margin-top: 4vw; }
.media-block.sand { background-color: var(--color-sand); }

/* Client Marquee */
.marquee-container {
  overflow: hidden;
  white-space: nowrap;
  padding: 4vw 0;
  position: relative;
  background-color: var(--bg-color);
  border-top: 1px solid rgba(26,26,26,0.1);
  border-bottom: 1px solid rgba(26,26,26,0.1);
}

.marquee-row {
  display: flex;
  width: fit-content;
  margin-bottom: 2rem;
}
.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-content {
  display: flex;
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 4rem);
  font-style: italic;
  padding-right: 2rem;
  will-change: transform;
}

.marquee-content span {
  padding: 0 1rem;
}

.marquee-row.left .marquee-content {
  animation: scroll-left 30s linear infinite;
}

.marquee-row.right .marquee-content {
  animation: scroll-right 30s linear infinite;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(0); }
}

/* About Section */
.about-section {
  max-width: 900px;
  margin: 0 auto;
}
.about-label {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 2rem;
  display: block;
  font-weight: 500;
}
.about-text p {
  font-size: clamp(1.25rem, 2.5vw, 2rem);
  line-height: 1.5;
  font-family: var(--font-serif);
  margin-bottom: 2rem;
}

/* Founder Letter (Neweno) */
.founder-letter {
  max-width: 800px;
  margin: 0 auto;
  padding-bottom: 10vw;
}
.founder-letter p {
  font-size: 1.25rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}
.founder-letter p:first-of-type::first-letter {
  font-family: var(--font-serif);
  font-size: 4rem;
  float: left;
  line-height: 1;
  padding-right: 0.5rem;
  color: var(--color-terracotta);
}

/* Services */
.services-intro {
  max-width: 1000px;
  margin-bottom: 6vw;
}
.services-intro h1 {
  font-size: clamp(3rem, 6vw, 5rem);
  margin-bottom: 2rem;
}
.services-intro h2 {
  font-family: var(--font-sans);
  font-weight: 400;
  font-size: 1.5rem;
  margin-bottom: 1rem;
}
.services-intro p {
  font-size: 1.25rem;
  max-width: 800px;
}
.divider {
  height: 1px;
  background-color: rgba(26,26,26,0.1);
  margin: 4vw 0;
}
.services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 4vw;
}
@media (min-width: 768px) {
  .services-grid {
    grid-template-columns: 1fr 2fr;
    gap: 8vw;
  }
}
.service-heading h3 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  position: sticky;
  top: 120px;
}
.service-items {
  display: flex;
  flex-direction: column;
  gap: 6vw;
}
.service-item h4 {
  font-size: 2rem;
  margin-bottom: 1rem;
}
.service-item p {
  font-size: 1.125rem;
  color: #4A4A4A;
}

/* Clients Grid */
.clients-header {
  margin-bottom: 6vw;
}
.clients-header h1 {
  font-size: clamp(3rem, 6vw, 5rem);
}
.clients-grid-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
}
@media (min-width: 768px) {
  .clients-grid-container {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 1024px) {
  .clients-grid-container {
    grid-template-columns: repeat(3, 1fr);
    column-gap: 4rem;
    row-gap: 5rem;
  }
}
.client-card h3 {
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}
.client-card p {
  font-size: 1rem;
  color: #4A4A4A;
  margin-bottom: 0;
}

/* Contact Page */
.contact-hero {
  min-height: calc(100vh - var(--nav-height));
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
}
.contact-hero h1 {
  font-size: clamp(4rem, 15vw, 15rem);
  line-height: 0.9;
  letter-spacing: -0.03em;
  margin-bottom: 4rem;
  text-transform: uppercase;
}
.contact-links {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
@media (min-width: 768px) {
  .contact-links {
    flex-direction: row;
    gap: 4rem;
  }
}
.contact-links a {
  font-family: var(--font-serif);
  font-size: 2rem;
  font-style: italic;
  position: relative;
  display: inline-block;
}
.contact-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0%;
  height: 1px;
  background-color: var(--text-color);
  transition: width 0.3s ease;
}
.contact-links a:hover::after {
  width: 100%;
}

